//! Event test vectors (ADR 0002, ADR 0007), published in
//! `docs/test-vectors/events.json` for other implementations.
//!
//! The file is generated by this test and must not drift: any change to
//! hashing or signing fails here. Regenerate (only before the format is
//! frozen) with `WATS_UPDATE_VECTORS=1 cargo test --test test_vectors`.

use ed25519_dalek::SigningKey;
use serde_json::{Map, Value, json};

use wats::event::{BlobRef, Draft, Kind};
use wats::wire::{
    BODY_HASH_KEY, EXT_KEY, HEADER_KEYS, RawEvent, UNHASHED_KEYS, digest, sign_value,
};

const PATH: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../docs/test-vectors/events.json"
);

fn obj(value: Value) -> Map<String, Value> {
    value.as_object().unwrap().clone()
}

fn case(name: &str, description: &str, seed: u8, event: Value) -> Value {
    let raw = RawEvent::from_value(event.clone()).expect("vector verifies");
    let d = digest(event.as_object().unwrap()).unwrap();
    json!({
        "name": name,
        "description": description,
        "secret_key": hex::encode([seed; 32]),
        "public_key": raw.author,
        "body_jcs": d.body_jcs.map(|b| String::from_utf8(b).unwrap()),
        "body_hash": d.body_hash,
        "header_jcs": String::from_utf8(d.header_jcs).unwrap(),
        "id": hex::encode(d.id),
        "pow_bits": raw.pow_bits(),
        "event": event,
    })
}

fn vectors() -> Value {
    let key = |seed: u8| SigningKey::from_bytes(&[seed; 32]);
    let note = Draft {
        net: "public".into(),
        kind: Some(Kind::Note),
        tags: vec!["lang:en".into()],
        text: "hello swarm".into(),
        ..Draft::default()
    }
    .sign(&key(1), 1_760_500_000, 0)
    .unwrap();
    let react = Draft {
        net: "public".into(),
        thread: Some(note.id.clone()),
        parent: Some(note.id.clone()),
        kind: Some(Kind::React),
        tags: vec!["cap:pdf".into(), "project:x".into()],
        text: "Useful, and the attached render checks out. Ünïcode: ok ✓".into(),
        data: obj(json!({"value": 1, "accept": true, "score": 0.5})),
        blobs: vec![BlobRef {
            hash: blake3::hash(b"report").to_hex().to_string(),
            name: "report.pdf".into(),
            size: 6,
            url: Some("https://example.com/report.pdf".into()),
        }],
    }
    .sign(&key(2), 1_760_500_100, 8)
    .unwrap();
    let react = serde_json::to_value(&react).unwrap();
    let v2 = sign_value(
        obj(
            json!({"v": 2, "ts": 1_760_600_000u64, "net": "public", "thread": null,
                   "parent": null, "kind": "poll", "ext": {"expires": 1_760_603_600u64}}),
        ),
        obj(json!({"text": "Which region for the next relay?", "options": ["eu", "us"]})),
        &key(3),
        4,
    )
    .unwrap();
    let tombstone = {
        let full = react.as_object().unwrap();
        let mut t: Map<String, Value> = full
            .iter()
            .filter(|(k, _)| {
                HEADER_KEYS.contains(&k.as_str())
                    || k.as_str() == EXT_KEY
                    || UNHASHED_KEYS.contains(&k.as_str())
            })
            .map(|(k, v)| (k.clone(), v.clone()))
            .collect();
        t.insert(BODY_HASH_KEY.into(), json!(digest(full).unwrap().body_hash));
        Value::Object(t)
    };
    json!({
        "description": "WeAreTheSwarm event test vectors. Each event verifies under the invariant core (ADR 0007): split header/body, body = BLAKE3(JCS(body)), id = BLAKE3(JCS(header + body)), sig = Ed25519 over the raw id. secret_key is the 32-byte Ed25519 seed.",
        "format_status": "provisional (ADR 0002): frozen before the first external install",
        "cases": [
            case("v1-note", "Minimal v1 root post.", 1, serde_json::to_value(&note).unwrap()),
            case("v1-react-reply", "v1 reply with data (float included), tags, a blob with URL, non-ASCII text, 8-bit proof of work.", 2, react),
            case("v2-opaque", "A future version: unknown kind, header extension `ext`, unknown body field. A v1 node verifies and relays it without understanding it.", 3, v2),
            case("v1-tombstone", "The v1-react-reply event with its body dropped: `body_hash` replaces the body fields; id and sig are unchanged.", 2, tombstone),
        ],
    })
}

#[test]
fn published_vectors_match_the_implementation() {
    let generated = vectors();
    if std::env::var_os("WATS_UPDATE_VECTORS").is_some() {
        let mut text = serde_json::to_string_pretty(&generated).unwrap();
        text.push('\n');
        std::fs::write(PATH, text).unwrap();
    }
    let published: Value =
        serde_json::from_str(&std::fs::read_to_string(PATH).expect("vectors file")).unwrap();
    assert_eq!(
        published, generated,
        "docs/test-vectors/events.json drifted"
    );
    for case in published["cases"].as_array().unwrap() {
        let raw = RawEvent::from_value(case["event"].clone()).unwrap();
        assert_eq!(raw.id, case["id"].as_str().unwrap());
        assert_eq!(
            blake3::hash(case["header_jcs"].as_str().unwrap().as_bytes())
                .to_hex()
                .as_str(),
            raw.id
        );
    }
}
